		public bool WipableTurret
		{
			get
			{
				if (owner == Main.myPlayer && sentry)
				{
					return !TurretShouldPersist();
				}
				return false;
			}
		}

		public float Opacity
		{
			get
			{
				return 1f - (float)alpha / 255f;
			}
			set
			{
				alpha = (int)MathHelper.Clamp((1f - value) * 255f, 0f, 255f);
			}
		}

