				}
				return false;
			}
		}

		public Point NetSectionCoordinates => new Point(Netplay.GetSectionX((int)position.X >> 4), Netplay.GetSectionY((int)position.Y >> 4));

		public static bool IsNPCIndexImmuneToProjectileType(int projectileType, int npcIndex)
		{
			return perIDStaticNPCImmunity[projectileType, npcIndex] <= Main.GameUpdateCount;
		}

		public static void ResetNPCSlotData(int npcIndex)
		{
			for (int i = 0; i < ProjectileID.Count; i++)
			{
				perIDStaticNPCImmunity[i, npcIndex] = 0u;
			}
			for (int j = 0; j < 1000; j++)
			{
				Main.projectile[j].localNPCImmunity[npcIndex] = 0;
			}
		}

		public void ResetStaticImmunityMatching(long expectedTime)
		{
			for (int i = 0; i < Main.maxNPCs; i++)
			{
				if (perIDStaticNPCImmunity[immunityIdentity, i] == expectedTime)
				{
					perIDStaticNPCImmunity[immunityIdentity, i] = 0u;
				}
			}
		}

		public static bool TryLookup(ProjectileKey key, out Projectile proj)
		{
			proj = Main.projectile[keyToIndex[key.Spawner, key.Index]];
			if ((int)proj.key == (int)key)
			{
				return true;
			}
			proj = null;
			return false;
		}

		public static void ClearAll()
		{
			Array.Clear(slotGenerations, 0, slotGenerations.Length);
			Array.Clear(keyToIndex, 0, keyToIndex.Length);
			for (int i = 0; i < 1000; i++)
			{
				Main.projectile[i] = new Projectile();
				Main.projectile[i].whoAmI = i;
			}
		}

		internal static void AddGameplaySnapshotComponents()
		{
			StateSnapshot.Gameplay.AddRef("Projectile.slotGenerations", () => slotGenerations, delegate(int[] v)
			{
				slotGenerations = v;
			});
			StateSnapshot.Gameplay.AddRef("Projectile.keyToIndex", () => keyToIndex, delegate(int[,] v)
			{
				keyToIndex = v;
			});
			StateSnapshot.Gameplay.AddRef("Projectile.perIDStaticNPCImmunity", () => perIDStaticNPCImmunity, delegate(uint[,] v)
			{
				perIDStaticNPCImmunity = v;
			});
		}

		public bool TurretShouldPersist()
		{
			switch (type)
			{
			case 663:
			case 665:
			case 667:
			case 677:
			case 678:
			case 679:
			case 688:
			case 689:
			case 690:
			case 691:
			case 692:
			case 693:
				return DD2Event.Ongoing;
			default:
				return false;
			}
		}

		private void TransformType(int typeToChangeInto)
