			}
			if (Type == 249)
			{
				projectile.frame = Main.rand.Next(5);
			}
			projectile.FinalizeProjectile();
			modifer?.Invoke(projectile);
			NetMessage.SendData(27, -1, -1, null, projectile.whoAmI);
