			if (customHitbox is MultiPointHitbox)
			{
				MultiPointHitbox multiPointHitbox = (MultiPointHitbox)customHitbox;
				CollisionVisualizer.VisualizeAABBvMultiPoint(targetRect, multiPointHitbox);
