						oldRot[num30] = oldRot[num30 - 1];
						oldSpriteDirection[num30] = oldSpriteDirection[num30 - 1];
					}
					oldPos[0] = position;
					oldRot[0] = velocity.ToRotation();
					oldSpriteDirection[0] = spriteDirection;
				}
				if (ProjectileID.Sets.IsADD2Turret[type] && DD2Event.Ongoing)
				{
					timeLeft++;
				}
				timeLeft--;
				if (timeLeft <= 0)
				{
					Kill();
				}
				if (penetrate == 0)
				{
					Kill();
				}
				if (!active || owner != Main.myPlayer)
				{
					continue;
				}
				if (netUpdate2)
				{
					netUpdate = true;
				}
				if (!active)
				{
					netSpam = 0;
				}
				if (netUpdate)
				{
					if (netSpam < 60)
					{
						netSpam += 5;
						NetMessage.SendData(27, -1, -1, null, i);
