		}

		private void RainbowBoulder_JumpToPosition(Vector2 targetPosition, Vector2 targetVelocity)
		{
			Vector2 v = targetPosition - base.Center;
			int num = 32;
			float num2 = Utils.Remap(v.Length(), 0f, 200f, 4f, num);
