		public void FinalizeProjectile()
		{
			if (aiStyle == 93)
			{
				rotation = (float)Math.Atan2(velocity.Y, velocity.X) + 1.57f;
			}
			else if (aiStyle == 113)
			{
				rotation = velocity.ToRotation() + (float)Math.PI / 2f;
				if (type == 1024)
				{
					rotation -= (float)Math.PI / 2f;
				}
			}
			else if (type == 121 || type == 122 || type == 123 || type == 124 || type == 597 || type == 125 || type == 126)
			{
				FinalizeProjectile_GemStaves();
			}
		}

		private void FinalizeProjectile_GemStaves()
		{
			GemStaffFeatures gemStaffFeatures = new GemStaffFeatures(ai[0]);
			int num = 0;
			int num2 = 0;
			int num3 = 1;
			if (gemStaffFeatures.FastThenSlow)
			{
				float num4 = 1f;
				num = Math.Max(num, (int)num4);
				num3 *= 2;
			}
			if (gemStaffFeatures.CanBounce)
			{
				float num5 = 2f;
				num = Math.Max(num, (int)num5);
			}
			if (gemStaffFeatures.BiggerHitbox)
			{
				float num6 = 1f;
				num = Math.Max(num, (int)num6);
			}
			if (gemStaffFeatures.ArPenSpread)
			{
				int num7 = 4;
				num2 += num7;
			}
			if (gemStaffFeatures.AllGems || gemStaffFeatures.AllGems2)
			{
				num = 2;
				num2 = 4;
				timeLeft = 90;
			}
			else
			{
				timeLeft *= num3;
			}
			maxPenetrate += num;
			penetrate += num;
			armorPenetration += num2;
		}

