		public void AI_AdjustPlayerItemRotationToFaceProjectile(int itemIDPlayerNeedsToBeHolding = -1, float minSpeed = 0f, bool ignoreAlphaCheck = false)
		{
			if (!ignoreAlphaCheck && alpha > 0)
			{
				return;
			}
			Player player = Main.player[owner];
			if (player.HeldItem == null || (itemIDPlayerNeedsToBeHolding > -1 && player.HeldItem.type != itemIDPlayerNeedsToBeHolding) || player.HeldItem.shoot != type)
			{
				return;
			}
			float x = velocity.X;
			float y = velocity.Y;
			Vector2 center = base.Center;
			x = player.MountedCenter.X - center.X;
			y = player.MountedCenter.Y + player.gfxOffY - center.Y;
			if (!(minSpeed > 0f) || !(Math.Abs(x) + Math.Abs(y) <= minSpeed))
			{
				int num = -1;
				if (base.Center.X < player.MountedCenter.X)
				{
					num = 1;
				}
				player.itemRotation = (float)Math.Atan2(y * (float)num, x * (float)num);
			}
		}

		private bool AI_DisplayDoll_ItemDisplay(Player doll, Item weapon, TEDisplayDoll.DisplayDollPose pose, float rotationAddon = 0f)
		{
			spriteDirection = direction;
			Vector2 spinningpoint = Vector2.UnitX * weapon.shootSpeed * weapon.scale;
			float num = 0f;
			if (pose.ItemAimRadians.HasValue)
			{
				num = pose.ItemAimRadians.Value;
			}
			spinningpoint = spinningpoint.RotatedBy(num);
			if (direction == -1)
			{
				spinningpoint.X *= -1f;
			}
			velocity = spinningpoint;
			position += spinningpoint;
			Vector2? handPosition = doll.HandPosition;
			if (handPosition.HasValue)
			{
				base.Center = handPosition.Value;
			}
			rotation = velocity.ToRotation() + rotationAddon * (float)doll.direction;
			if (doll.direction == -1)
			{
				rotation += (float)Math.PI / 2f;
			}
			return true;
		}

