		public static Color GetLightningColor(int type)
		{
			switch (type)
			{
			case 1117:
				return new Color(60, 120, 255);
			case 1122:
				return new Color(255, 60, 60);
			case 1091:
				if (Main.moreLightningSeed && Main.noLightningSeed)
