		private int PackTargetIndex(int npcIndex = -1, int playerIndex = -1)
		{
			if (npcIndex != -1)
			{
				return npcIndex;
			}
			if (playerIndex != -1)
			{
				return -2 - playerIndex;
			}
			return -1;
