		private void UnpackTargetIndex(float aiValue, out int npcIndex, out int playerIndex)
		{
			npcIndex = -1;
			playerIndex = -1;
			if (aiValue >= 0f)
			{
				npcIndex = (int)aiValue;
			}
			if (aiValue <= -2f)
			{
				playerIndex = -(int)aiValue - 2;
			}
		}

