		public int FindTargetWithLineOfSight(float maxRange = 800f, ICollection<int> ignoreTargets = null)
		{
			return FindTargetWithLineOfSight(this, maxRange, ignoreTargets);
		}

		public static int FindTargetWithLineOfSight(Entity targeter, float maxRange = 800f, ICollection<int> ignoreTargets = null)
		{
			float num = maxRange;
			int result = -1;
			Projectile projectile = ((targeter is Projectile) ? ((Projectile)targeter) : null);
			for (int i = 0; i < Main.maxNPCs; i++)
			{
				if (ignoreTargets != null && ignoreTargets.Contains(i))
				{
					continue;
				}
				NPC nPC = Main.npc[i];
				bool flag = nPC.CanBeChasedBy(targeter);
				if (projectile != null && projectile.localNPCImmunity[i] != 0)
				{
					flag = false;
				}
				if (flag)
				{
					float num2 = targeter.Distance(Main.npc[i].Center);
					if (num2 < num && Collision.CanHit(targeter.position, targeter.width, targeter.height, nPC.position, nPC.width, nPC.height))
					{
						num = num2;
						result = i;
					}
				}
			}
			return result;
		}

