			Player player = Main.player[owner];
			bool flag = owner == 255;
			float num = 4f;
			float num2 = 500f;
			float num3 = num2 / 2f;
			if (owner == Main.myPlayer && extraUpdates == 0)
			{
				float num4 = ai[0];
				if (ai[0] == 0f)
				{
					ai[0] = num3;
				}
				float num5 = ai[0];
				if (player.channel)
				{
					num5 -= 5f;
				}
				if (player.controlUseItem && player.itemAnimation == 0)
				{
					num5 += 5f;
				}
				ai[0] = MathHelper.Clamp(num5, num, num2);
