		public void ApplyHarpyCharm(int npcTargetIndex, int itemID)
		{
			float maxChange = (float)Math.PI;
			bool flag = itemID == 6181;
			bool flag2 = itemID == 6180;
			velocity = Utils.rotateTowards(base.Center, velocity, Main.npc[npcTargetIndex].Center, maxChange);
			velocity *= 1f;
			AI_001_Features aI_001_Features = new AI_001_Features(ai[2]);
			aI_001_Features.HarpyCharmed = true;
			if (flag)
			{
				aI_001_Features.PhoenixQuivered = true;
			}
			if (flag2)
			{
				aI_001_Features.SeraphNecklaced = true;
			}
			ai[2] = aI_001_Features.Bits;
			if (timeLeft > 300)
			{
				timeLeft = 300;
			}
			NetMessage.SendData(27, -1, -1, null, whoAmI);
			ParticleOrchestrator.RequestParticleSpawn(clientOnly: false, flag2 ? ParticleOrchestraType.SeraphNecklace : (flag ? ParticleOrchestraType.PhoenixQuiver : ParticleOrchestraType.HarpyCharm), new ParticleOrchestraSettings
			{
				PositionInWorld = base.Center,
				MovementVector = velocity
			});
		}

