		public bool CanGetPickedUpBySentryBackpack()
		{
			if (!sentry)
			{
				return false;
			}
			if (owner != Main.myPlayer)
			{
				return false;
			}
			Player player = Main.player[owner];
			if (!player.accSentryBackpack || player.accSentryBackpackGrabCooldown > 0)
			{
				return false;
			}
			if (!base.Hitbox.Intersects(player.Hitbox))
			{
				return false;
			}
			return true;
		}

